/*
 * cczp_sub_mod modulo the P-256, P-384 and P-521 primes. When s < t the
 * difference wraps to s - t + b^n (b = 2^64, n units); the function used to
 * reduce that and then add the prime, which is only s - t mod p when
 * b^n - p is tiny, so it failed whenever t - s was at most b^n - p: on rare
 * inputs for P-256 and P-384 and on almost every input for P-521, which made
 * every P-521 signature fail to verify. Expected values are (s - t) % p from
 * Python big integers; s and t are reduced, as at every caller.
 *
 * Needs 64-bit cc_unit. Build and run from the repository root (on an aarch64
 * host add -D__arm64__):
 *   clang -fsanitize=address,undefined -fno-sanitize-recover=all -w \
 *     -Iinclude $(sed -n '/set(corecrypto_sources/,/^)/p' CMakeLists.txt \
 *     | grep 'src/' | tr -d '\t ' | sort -u) tests/standalone/cczp_sub_mod.c \
 *     -o /tmp/cczp_sub_mod && /tmp/cczp_sub_mod
 */
#include <corecrypto/ccec.h>
#include <corecrypto/cczp.h>
