static ccec_const_cp_t curve(unsigned bits) {
	switch (bits) {
		case 256: return ccec_cp_256();
		case 384: return ccec_cp_384();
		default: return ccec_cp_521();
	}
}

int main(void) {
	int failures = 0;
	size_t count = sizeof(cases) / sizeof(cases[0]);

	for (size_t i = 0; i < count; i++) {
		cczp_const_t zp = (cczp_const_t)curve(cases[i].curve).zp;
		const cc_size k = cases[i].k;
		if (cczp_n(zp) != k) {
			printf("FAIL case %zu: P-%u has %zu units, expected %zu\n", i, cases[i].curve, (size_t)cczp_n(zp), (size_t)k);
			failures++;
			continue;
		}
		cc_unit s[9], t[9], r[9];
		memcpy(s, cases[i].s, sizeof s);
		memcpy(t, cases[i].t, sizeof t);
		memset(r, 0xa5, sizeof r);
		cczp_sub_mod(k, r, s, t, zp);
		if (memcmp(r, cases[i].expected, k * sizeof(cc_unit)) != 0) {
			printf("FAIL case %zu: P-%u s - t mod p wrong\n", i, cases[i].curve);
			failures++;
		}
	}

	printf("%d failure(s) in %zu cases\n", failures, count);
	return failures != 0;
}

